        b2_xsq_hi67     = $signed({n_a6_b2xsq_hi_c[65], n_a6_b2xsq_hi_c}) + $signed({{33{n_a5_b2xsq_lo_c[65]}}, n_a5_b2xsq_lo_c[65:32]});
        b2_xsq128       = $signed({{29{b2_xsq_hi67[66]}}, b2_xsq_hi67, n_a5_b2xsq_lo_c[31:0]});
        b0_b1_q32       = $signed({b0_eff64_q[63], b0_eff64_q}) + $signed({n_a1_b1_x_q[63], n_a1_b1_x_q});
        g0_op_hi81      = $signed(b2_xsq128[97:17]) + $signed({{16{b0_b1_q32[64]}}, b0_b1_q32});
        n_a7_g0_op_c    = $signed({{30{g0_op_hi81[80]}}, g0_op_hi81, b2_xsq128[16:0]});
        n_a8_g1_op_c    = $signed({{16{b1_q[31]}}, b1_q, 16'd0}) + n_a3_b2_x_c;
        j0_in           = clamp_j0_sym64($signed(state_w_q[0]));
        j1_in           = clamp_j1_sym64($signed(state_w_q[1]));
