        j1_sub_in       = sub_valid ? state_w_q[7][63:48] : 16'd0;
        j0_q49          = $signed({j0_in[61:0], j0_sub_in});
        n_a9_j1_q32_c   = $signed({j1_in[47:0], j1_sub_in});
        g0_au_hi78      = $signed(j0_q49[94:17]) - $signed({{14{b0_eff64_q[63]}}, b0_eff64_q});
        n_a9_g0_au_c    = $signed({{33{g0_au_hi78[77]}}, g0_au_hi78, j0_q49[16:0]});
        n_a10_op_mask_c = op_mask_q;
        n_a10_g0_c      = n_a10_op_mask_c ? n_a7_g0_op_c : n_a9_g0_au_c;
        n_a10_g1_c      = n_a10_op_mask_c ? n_a8_g1_op_c : n_a9_j1_q32_c;
        n_a10_has_r2_c  = r2_nz_c;
        n_a10_active_c  = (n_a10_g0_c != 128'sd0) & ((n_a10_g1_c != 64'sd0) | n_a10_has_r2_c);

        // Cone B (`B6`, `B7`, `B8`)
        n_b6_g1_sq_c  = ($signed({{62{n_b1_g1_hl_c[65]}}, n_b1_g1_hl_c}) <<< 33) +
                        $signed({n_b2_g1_hh_c[63:0], n_b0_g1_ll_c[63:0]});
        b7_hi96       = $signed({n_b5_g0r2_2_c[63:0], 32'd0}) +
                        $signed({{30{n_b4_g0r2_1_c[65]}}, n_b4_g0r2_1_c}) +
                        $signed({{62{n_b3_g0r2_0_c[65]}}, n_b3_g0r2_0_c[65:32]});
