        g1_dc128        = $signed({{29{g1_dc_hi67[66]}}, g1_dc_hi67, n_c2_g1dc_lo_q[31:0]});
        r2_dsq_hi67     = $signed({n_c6_r2dsq_hi_c[65], n_c6_r2dsq_hi_c}) + $signed({{33{n_c5_r2dsq_lo_c[65]}}, n_c5_r2dsq_lo_c[65:32]});
        r2_dsq128       = $signed({{29{r2_dsq_hi67[66]}}, r2_dsq_hi67, n_c5_r2dsq_lo_c[31:0]});
        push_hi98       = $signed({g1_dc128[96:0], 1'b0}) + $signed(r2_dsq128[97:0]);
        cand_s99        = $signed({g0_s98_q[97], g0_s98_q}) + $signed({push_hi98[97], push_hi98});
        n_c7_g0_cand_c  = $signed({{29{cand_s99[98]}}, cand_s99});
        lyap_ok         = (~fast_path_q) & (abs128(n_c7_g0_cand_q) <= abs128(g0_q));
        delta_act       = lyap_ok ? n_c0_dc_q : 33'sd0;
        n_c8_xp_c       = $signed(x_in_clamped_c + delta_act[31:0]);
        delta_mag33     = delta_act[32] ? (33'd0 - $unsigned(delta_act)) : $unsigned(delta_act);
        n_c8_dt_res_c   = {31'd0, delta_mag33};
        n_c8_g0_post_c  = lyap_ok ? n_c7_g0_cand_q : g0_q;
        n_c8_g1_post_c  = g1_q + (lyap_ok ? n_c4_r2_dc_q : 64'sd0);
        j0_op_out       = sym_shr128_33(n_c8_g0_post_c);
        j1_op_out       = sym_shr64_16(n_c8_g1_post_c);
        j0_au_next97    = {$unsigned(n_c8_g0_post_c[96:17]) + {{16{b0_eff64_q[63]}}, $unsigned(b0_eff64_q)}, n_c8_g0_post_c[16:0]};
        j0_au_out       = clamp_j0_sym64($signed(j0_au_next97[96:33]));
        j1_au_out       = clamp_j1_sym64($signed({{16{n_c8_g1_post_c[63]}}, n_c8_g1_post_c[63:16]}));
        n_c9_j0_next_c  = $unsigned(op_mask_q ? j0_op_out : j0_au_out);
        n_c9_j1_next_c  = $unsigned(op_mask_q ? j1_op_out : j1_au_out);
        n_c9_sub_next_c = op_mask_q ? 64'd0 : {n_c8_g1_post_c[15:0], 15'd0, j0_au_next97[32:0]};
