                           : ((n_c8_xp_c < b_exit_q) ? {8'd0, next_lo_q} : state_w_q[5][31:16]);
        n_c10_chart_next_c = raw_chart & cap_mask16_q;
        n_c10_mode_proj_c  = (mode_req_q & (~kan_lock_q)) | (state_w_q[5][15:0] & kan_lock_q);
        n_c10_conv_c       = (abs128(n_c8_g0_post_c) <= 128'h0000_0000_0000_0000_0000_0008_0000_0000);
        if (&{1'b0, j0_in[63:62], n_b0_g1_ll_c[65:64], n_b2_g1_hh_c[65:64], n_b5_g0r2_2_c[65:64], b2_xsq128[127:98], g1_dc128[127:97], r2_dsq128[127:98], n_a7_g0_op_c[127:98], n_a9_g0_au_c[127:95], n_a10_g0_c[127:98], n_d0_div_num_c[126:99], n_c7_g0_cand_c[127:99], n_c8_g0_post_c[127:99], delta_mag33[32], n_c8_dt_res_c[63:32]}) begin end
    end

    // =========================================================================
    // Pass-2 Clock-Enabled Shared Physical Cut Register Steering (`0` idle flips)
    // =========================================================================
    always_comb begin
        sh_lane0_we_c = 1'b0;
        sh_lane1_we_c = 1'b0;
        sh_lane2_we_c = 1'b0;
        sh_lane3_we_c = 1'b0;
        case (st_q)
            4'd1: begin
                // a1_b1_x [1 -> 2] -> sh_lane0
                sh_lane0_we_c = 1'b1;
                // a2_x_sq [1 -> 2] -> sh_lane1
                sh_lane1_we_c = 1'b1;
            end
            4'd3: begin
                // b6_g1_sq_lo [3 -> 5] -> sh_lane0
                sh_lane0_we_c = 1'b1;
                // b6_g1_sq_hi [3 -> 5] -> sh_lane1
                sh_lane1_we_c = 1'b1;
            end
            4'd4: begin
                // b7_g0_r2_lo [4 -> 5] -> sh_lane2
                sh_lane2_we_c = 1'b1;
                // b7_g0_r2_hi [4 -> 5] -> sh_lane3
                sh_lane3_we_c = 1'b1;
            end
            4'd9: begin
                // c0_dc [9 -> 11] -> sh_lane3
                sh_lane3_we_c = 1'b1;
                // c1_dsq [9 -> 10] -> sh_lane1
                sh_lane1_we_c = 1'b1;
                // c2_g1dc_lo [9 -> 10] -> sh_lane0
                sh_lane0_we_c = 1'b1;
                // c3_g1dc_hi [9 -> 10] -> sh_lane2
                sh_lane2_we_c = 1'b1;
            end
            4'd10: begin
                // c4_r2_dc [10 -> 11] -> sh_lane1
                sh_lane1_we_c = 1'b1;
                // c7_g0_cand_lo [10 -> 11] -> sh_lane0
                sh_lane0_we_c = 1'b1;
                // c7_g0_cand_hi [10 -> 11] -> sh_lane2
                sh_lane2_we_c = 1'b1;
            end
            default: begin end
        endcase
        if ((st_q == 4'd1) || (st_q == 4'd9)) sh_lane0_d_c = dsp_prod_w[1];
        else if ((st_q == 4'd3)) sh_lane0_d_c = {2'd0, $unsigned(n_b6_g1_sq_c[63:0])};
        else sh_lane0_d_c = {2'd0, $unsigned(n_c7_g0_cand_c[63:0])};
        if ((st_q == 4'd1) || (st_q == 4'd9) || (st_q == 4'd10)) sh_lane1_d_c = dsp_prod_w[0];
        else sh_lane1_d_c = {2'd0, $unsigned(n_b6_g1_sq_c[127:64])};
