            iter_q       <= 5'd0;
            done_q       <= 1'b0;
            state_w_q    <= 512'd0;
            b0_q         <= 32'sd0;
            b1_q         <= 32'sd0;
            b2_q         <= 32'sd0;
            b_exit_q     <= 32'sd0;
            b_enter_q    <= 32'sd0;
            dt_max_q     <= 32'sd1;
            u_gain_q     <= 32'sd0;
            u_in_q       <= 32'sd0;
            next_lo_q    <= 8'd0;
            next_hi_q    <= 8'd0;
            kan_lock_q   <= 16'd0;
            cap_mask16_q <= 16'hFFFF;
            mode_req_q   <= 16'd0;
            fast_path_q  <= 1'b0;
            b0_eff64_q   <= 64'sd0;
            g0_s98_q     <= 98'sd0;
            g1_q         <= 64'sd0;
            div_neg_q    <= 1'b0;
            pre_sat_q    <= 1'b0;
            sr_rem_q     <= 64'd0;
            sr_acc_q     <= 64'd0;
            sr_aux_q     <= 128'd0;
            sh_lane0_q   <= 66'd0;
            sh_lane1_q   <= 66'd0;
            sh_lane2_q   <= 66'd0;
            sh_lane3_q   <= 64'd0;
