                                    3'd2: state_w_q[2] <= wr_data_i;
                                    3'd3: state_w_q[3] <= wr_data_i;
                                    3'd4: state_w_q[4] <= wr_data_i;
                                    3'd5: state_w_q[5] <= wr_data_i;
                                    3'd6: state_w_q[6] <= wr_data_i;
                                    3'd7: state_w_q[7] <= wr_data_i;
