                        st_q        <= 4'd11;
                    end else if (!n_a10_has_r2_c) begin
                        st_q        <= 4'd7;
                    end else begin
                        st_q        <= 4'd3;
                    end
                end
                4'd3: begin
                    st_q <= 4'd4;
                end
                4'd4: begin
                    st_q <= 4'd5;
