        f_past_next_hi_q <= next_hi_q;
        f_past_cap_q     <= cap_mask16_q;
        f_past_mreq_q    <= mode_req_q;
        f_past_mode_q    <= state_w_q[5][15:0];
        f_past_lock_q    <= kan_lock_q;
    end
    always_comb begin
        if (!rst_n) begin
            assert (st_q == 4'd0);
            assert (ready_o && !done_o && !fast_path_q);
            assert (dt_max_q == 32'sd1);
            assert (cap_mask16_q == 16'hFFFF);
        end
        if (ready_o) begin
            assert (dsp_en_c[0] == 1'b0);
            assert (dsp_en_c[1] == 1'b0);
            assert (dsp_en_c[2] == 1'b0);
            assert (sh_lane0_we_c == 1'b0);
            assert (sh_lane1_we_c == 1'b0);
            assert (sh_lane2_we_c == 1'b0);
            assert (sh_lane3_we_c == 1'b0);
            assert (rad2_en_c == 1'b0);
        end
        if (f_past_valid_q && f_past_rst_n_q && rst_n) begin
            if (!f_past_ready_q) begin
                assert (b0_q == f_past_b0_q);
                assert (b1_q == f_past_b1_q);
                assert (b2_q == f_past_b2_q);
                assert (b_exit_q == f_past_b_exit_q);
                assert (b_enter_q == f_past_b_enter_q);
                assert (dt_max_q == f_past_dt_max_q);
                assert (u_gain_q == f_past_u_gain_q);
                assert (u_in_q == f_past_u_in_q);
                assert (next_lo_q == f_past_next_lo_q);
                assert (next_hi_q == f_past_next_hi_q);
                assert (kan_lock_q == f_past_lock_q);
                assert (cap_mask16_q == f_past_cap_q);
                assert (mode_req_q == f_past_mreq_q);
                if (int'(f_past_st_q) != (NUM_STATES - 1)) begin
                    assert (!done_o);
                    assert (state_w_q == f_past_state_w_q);
                end
            end
            if (int'(f_past_st_q) >= NUM_STATES) begin
                assert (st_q == 4'd0);
                assert (ready_o && !done_o && !fast_path_q);
            end
            if (done_o) begin
                assert (ready_o);
                assert (int'(f_past_st_q) == (NUM_STATES - 1));
                assert ((state_w_q[5][15:0] & f_past_lock_q) == (f_past_mode_q & f_past_lock_q));
            end
        end
    end
`endif
endmodule

module ele_flow_atlas_top #(
    parameter int MAX_CHARTS = 16
) (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        cmd_valid_i,
    input  logic [2:0]  cmd_op_i,
    input  logic [2:0]  cmd_word_i,
    input  logic [15:0] cmd_aux_i,
    input  logic [63:0] cmd_data_i,
    output logic        ready_o,
    output logic        step_done_o,
    output logic        swap_done_o,
    output logic        swap_accepted_o,
    output logic [63:0] rd_data_o
);
    /* verilator lint_off UNUSEDPARAM */
    localparam int SLOT_W             = (MAX_CHARTS <= 2) ? 1 : $clog2(MAX_CHARTS);
    localparam int SRAM_DEPTH         = (MAX_CHARTS * 2) * 8;
    localparam int SRAM_AW            = $clog2(SRAM_DEPTH);
    localparam int SWAP_COMMIT_CYCLES = 14;
    localparam logic [SLOT_W:0] SHADOW_SLOT = {1'b1, {SLOT_W{1'b0}}};
    localparam logic [15:0]     HW_MASK16   = 16'(MAX_CHARTS - 1);
    /* verilator lint_on UNUSEDPARAM */

    // 64-bit Bus Command Opcodes
    localparam logic [2:0] CMD_NOP         = 3'd0;
    localparam logic [2:0] CMD_LOAD_STATE  = 3'd1;
    localparam logic [2:0] CMD_SET_CAP     = 3'd2;
    localparam logic [2:0] CMD_WRITE_CHART = 3'd3;
    localparam logic [2:0] CMD_STAGE_CAND  = 3'd4;
    localparam logic [2:0] CMD_STEP        = 3'd5;
    localparam logic [2:0] CMD_SWAP        = 3'd6;

    localparam logic [2:0] TOP_IDLE        = 3'd0;
    localparam logic [2:0] TOP_FETCH_BOUND = 3'd1;
    localparam logic [2:0] TOP_START_CORE  = 3'd2;
    localparam logic [2:0] TOP_WAIT_CORE   = 3'd3;
    localparam logic [2:0] TOP_SWAP_CHK    = 3'd4;
    localparam logic [2:0] TOP_SWAP_COMMIT = 3'd5;

    function automatic logic signed [31:0] clamp_top64_to_32(input logic [63:0] raw);
        logic ovf_pos, ovf_neg;
        begin
            ovf_pos = (~raw[63]) & (|raw[62:31]);
            ovf_neg = raw[63] & ((~(&raw[62:31])) | (raw[30:0] == 31'd0));
            if (ovf_pos)      clamp_top64_to_32 = 32'sh7FFF_FFFF;
            else if (ovf_neg) clamp_top64_to_32 = -32'sh7FFF_FFFF;
            else              clamp_top64_to_32 = $signed(raw[31:0]);
        end
    endfunction

    logic [2:0]             top_st_q;
    logic [3:0]             sub_beat_q;
    logic [15:0]            cap_mask_q;
    logic [MAX_CHARTS-1:0]  slot_valid_q;
    logic [SLOT_W-1:0]      act_slot_q;
    logic                   bound_cache_valid_q;
    logic [SLOT_W-1:0]      bound_cache_slot_q;
    logic signed [31:0]     u_ext_hold32_q;
    logic [5:0]             cand_staged_mask_q;
    logic                   cand_b_ok_q;
    logic                   cand_dt_ok_q;
    logic [7:0]             cand_next_lo_q;
    logic [7:0]             cand_next_hi_q;
    logic [SLOT_W-1:0]      swap_slot_q;
    logic [31:0]            swap_epoch_q;
    logic                   step_done_q;
    logic                   swap_done_q;
    logic                   swap_acc_q;

    logic                  sram_ce_c;
    logic                  sram_we_c;
    logic [SRAM_AW-1:0]    sram_addr_c;
    logic [63:0]           sram_wdata_c;
    logic [63:0]           sram_rdata_w;

    ele_sram_1rw64 #(
        .DEPTH  (SRAM_DEPTH),
        .ADDR_W (SRAM_AW)
    ) u_chart_sram (
        .clk     (clk),
        .ce_i    (sram_ce_c),
        .we_i    (sram_we_c),
        .addr_i  (sram_addr_c),
        .wdata_i (sram_wdata_c),
        .rdata_o (sram_rdata_w)
    );

    logic        core_wr_valid_c;
    logic [1:0]  core_wr_kind_c;
    logic [2:0]  core_wr_idx_c;
    logic [63:0] core_wr_data_c;
    logic        core_ready_w;
    logic        core_done_w;
    logic [2:0]  core_rd_idx_c;
    logic [63:0] core_rd_data_w;

    ele_flow_core u_core (
        .clk        (clk),
        .rst_n      (rst_n),
        .wr_valid_i (core_wr_valid_c),
        .wr_kind_i  (core_wr_kind_c),
        .wr_idx_i   (core_wr_idx_c),
        .wr_data_i  (core_wr_data_c),
        .ready_o    (core_ready_w),
        .done_o     (core_done_w),
        .rd_idx_i   (core_rd_idx_c),
        .rd_data_o  (core_rd_data_w)
    );

    logic [31:0] swap_cur_ep_c;
    logic        swap_fw_ok_c;
    logic [7:0]  cand_staged_pad_c;
    assign cand_staged_pad_c = {2'b00, cand_staged_mask_q};
    always_comb begin
        swap_cur_ep_c = slot_valid_q[swap_slot_q] ? sram_rdata_w[63:32] : 32'd0;
        swap_fw_ok_c  = (swap_epoch_q > swap_cur_ep_c) &
                        ({8'd0, cand_next_lo_q} <= cap_mask_q) &
                        ({8'd0, cand_next_hi_q} <= cap_mask_q) &
                        cand_dt_ok_q &
                        cand_b_ok_q;
    end

    logic [SLOT_W-1:0] step_slot_c;
    logic              step_cache_hit_c;
    logic [SLOT_W-1:0] swap_req_slot_c;
    logic [SLOT_W-1:0] wr_chart_slot_c;
    wire               unused_aux_hi_ok = &{1'b0, cmd_aux_i[15:SLOT_W]};

    always_comb begin
        core_rd_idx_c    = (top_st_q == TOP_IDLE && cmd_valid_i && cmd_op_i == CMD_STEP) ? 3'd5 : cmd_word_i;
        step_slot_c      = core_rd_data_w[16 +: SLOT_W] & cap_mask_q[SLOT_W-1:0];
        step_cache_hit_c = bound_cache_valid_q & (step_slot_c == bound_cache_slot_q);
        swap_req_slot_c  = cmd_aux_i[SLOT_W-1:0] & cap_mask_q[SLOT_W-1:0];
        wr_chart_slot_c  = cmd_aux_i[SLOT_W-1:0];

        sram_ce_c       = 1'b0;
        sram_we_c       = 1'b0;
        sram_addr_c     = {SRAM_AW{1'b0}};
        sram_wdata_c    = 64'd0;

        core_wr_valid_c = 1'b0;
        core_wr_kind_c  = 2'd0;
        core_wr_idx_c   = 3'd0;
        core_wr_data_c  = 64'd0;

        case (top_st_q)
            TOP_IDLE: begin
                if (cmd_valid_i && core_ready_w) begin
                    case (cmd_op_i)
                        CMD_LOAD_STATE: begin
                            core_wr_valid_c = 1'b1;
                            core_wr_kind_c  = 2'd0;
                            core_wr_idx_c   = cmd_word_i;
                            core_wr_data_c  = cmd_data_i;
                        end
                        CMD_STAGE_CAND: begin
                            if (cmd_word_i < 3'd6) begin
                                sram_ce_c    = 1'b1;
                                sram_we_c    = 1'b1;
                                sram_addr_c  = {SHADOW_SLOT, cmd_word_i};
                                sram_wdata_c = cmd_data_i;
                            end
                        end
                        CMD_WRITE_CHART: begin
                            sram_ce_c    = 1'b1;
                            sram_we_c    = 1'b1;
                            sram_addr_c  = {1'b0, wr_chart_slot_c, cmd_word_i};
                            sram_wdata_c = cmd_data_i;
                        end
                        CMD_STEP: begin
                            if (!step_cache_hit_c) begin
                                sram_ce_c   = 1'b1;
                                sram_we_c   = 1'b0;
                                sram_addr_c = {1'b0, step_slot_c, 3'd0};
                            end
                            core_wr_valid_c = 1'b1;
                            core_wr_kind_c  = 2'd2;
                            core_wr_idx_c   = 3'd0;
                            core_wr_data_c  = {32'd0, cmd_aux_i, cap_mask_q};
                        end
                        CMD_SWAP: begin
                            sram_ce_c   = 1'b1;
                            sram_we_c   = 1'b0;
                            sram_addr_c = {1'b0, swap_req_slot_c, 3'd6};
                        end
                        default: begin end
                    endcase
                end
            end

            TOP_FETCH_BOUND: begin
                core_wr_valid_c = 1'b1;
                core_wr_kind_c  = 2'd1;
                core_wr_idx_c   = sub_beat_q[2:0];
                core_wr_data_c  = slot_valid_q[act_slot_q] ? sram_rdata_w : 64'd0;
                if (sub_beat_q < 4'd5) begin
                    sram_ce_c   = 1'b1;
                    sram_we_c   = 1'b0;
                    sram_addr_c = {1'b0, act_slot_q, sub_beat_q[2:0] + 3'd1};
                end
            end

            TOP_START_CORE: begin
                core_wr_valid_c = 1'b1;
                core_wr_kind_c  = 2'd2;
                core_wr_idx_c   = 3'd1;
                core_wr_data_c  = {{32{u_ext_hold32_q[31]}}, $unsigned(u_ext_hold32_q)};
            end
            TOP_SWAP_CHK: begin
                if (swap_fw_ok_c) begin
                    sram_ce_c   = 1'b1;
                    sram_we_c   = 1'b0;
                    sram_addr_c = {SHADOW_SLOT, 3'd0};
                end
            end
            TOP_SWAP_COMMIT: begin
                sram_ce_c = 1'b1;
                if (sub_beat_q < 4'd11) begin
                    if (!sub_beat_q[0]) begin
                        sram_we_c    = 1'b1;
                        sram_addr_c  = {1'b0, swap_slot_q, sub_beat_q[3:1]};
                        sram_wdata_c = cand_staged_pad_c[sub_beat_q[3:1]] ? sram_rdata_w : 64'd0;
                    end else begin
                        sram_we_c   = 1'b0;
                        sram_addr_c = {SHADOW_SLOT, sub_beat_q[3:1] + 3'd1};
                    end
                end else if (sub_beat_q == 4'd11) begin
                    sram_we_c    = 1'b1;
                    sram_addr_c  = {1'b0, swap_slot_q, 3'd7};
                    sram_wdata_c = 64'd0;
                end else begin
                    sram_we_c    = 1'b1;
                    sram_addr_c  = {1'b0, swap_slot_q, 3'd6};
                    sram_wdata_c = {swap_epoch_q, 32'd0};
                end
            end
            default: begin end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            top_st_q            <= TOP_IDLE;
            sub_beat_q          <= 4'd0;
            cap_mask_q          <= HW_MASK16;
            slot_valid_q <= {MAX_CHARTS{1'b0}};
            act_slot_q          <= {SLOT_W{1'b0}};
            bound_cache_valid_q <= 1'b0;
            bound_cache_slot_q  <= {SLOT_W{1'b0}};
            u_ext_hold32_q      <= 32'sd0;
            cand_staged_mask_q  <= 6'd0;
            cand_b_ok_q         <= 1'b1;
            cand_dt_ok_q        <= 1'b0;
            cand_next_lo_q      <= 8'd0;
            cand_next_hi_q      <= 8'd0;
            swap_slot_q         <= {SLOT_W{1'b0}};
            swap_epoch_q        <= 32'd0;
            step_done_q         <= 1'b0;
            swap_done_q         <= 1'b0;
            swap_acc_q          <= 1'b0;
        end else begin
            step_done_q <= 1'b0;
            swap_done_q <= 1'b0;
            swap_acc_q  <= 1'b0;

            case (top_st_q)
                TOP_IDLE: begin
                    if (cmd_valid_i && core_ready_w) begin
                        case (cmd_op_i)
                            CMD_SET_CAP: begin
                                cap_mask_q <= cmd_data_i[15:0] & HW_MASK16;
                            end
                            CMD_STAGE_CAND: begin
                                if (cmd_word_i < 3'd6) begin
                                    cand_staged_mask_q[cmd_word_i] <= 1'b1;
                                    if (cmd_word_i == 3'd3) begin
                                        cand_b_ok_q <= ($signed(cmd_data_i[63:32]) <= $signed(cmd_data_i[31:0]));
                                    end else if (cmd_word_i == 3'd4) begin
                                        cand_dt_ok_q <= ($signed(cmd_data_i[63:32]) > 32'sd0);
                                    end else if (cmd_word_i == 3'd5) begin
                                        cand_next_lo_q <= cmd_data_i[31:24];
                                        cand_next_hi_q <= cmd_data_i[23:16];
                                    end
                                end
                            end
                            CMD_WRITE_CHART: begin
                                if (wr_chart_slot_c == bound_cache_slot_q) begin
                                    bound_cache_valid_q <= 1'b0;
                                end
                                if (cmd_word_i == 3'd7) begin
                                    slot_valid_q[wr_chart_slot_c] <= 1'b1;
                                end
                            end
                            CMD_STEP: begin
                                act_slot_q     <= step_slot_c;
                                u_ext_hold32_q <= clamp_top64_to_32(cmd_data_i);
                                sub_beat_q     <= 4'd0;
                                top_st_q       <= step_cache_hit_c ? TOP_START_CORE : TOP_FETCH_BOUND;
                            end
                            CMD_SWAP: begin
                                swap_slot_q  <= swap_req_slot_c;
                                swap_epoch_q <= cmd_data_i[31:0];
                                top_st_q     <= TOP_SWAP_CHK;
                            end
                            default: begin end
                        endcase
                    end
                end
                TOP_FETCH_BOUND: begin
                    if (sub_beat_q >= 4'd5) begin
                        bound_cache_valid_q <= 1'b1;
                        bound_cache_slot_q  <= act_slot_q;
                        top_st_q            <= TOP_START_CORE;
                    end else begin
                        sub_beat_q <= sub_beat_q + 4'd1;
                    end
                end
                TOP_START_CORE: begin
                    top_st_q <= TOP_WAIT_CORE;
                end
                TOP_WAIT_CORE: begin
                    if (core_done_w) begin
                        step_done_q <= 1'b1;
                        top_st_q    <= TOP_IDLE;
                    end
                end
                TOP_SWAP_CHK: begin
                    if (!swap_fw_ok_c) begin
                        swap_done_q <= 1'b1;
                        swap_acc_q  <= 1'b0;
                        top_st_q    <= TOP_IDLE;
                    end else begin
                        sub_beat_q <= 4'd0;
                        top_st_q   <= TOP_SWAP_COMMIT;
                    end
                end
                TOP_SWAP_COMMIT: begin
                    if (sub_beat_q >= 4'd12) begin
                        if (swap_slot_q == bound_cache_slot_q) begin
                            bound_cache_valid_q <= 1'b0;
                        end
                        slot_valid_q[swap_slot_q] <= 1'b1;
                        swap_done_q               <= 1'b1;
                        swap_acc_q                <= 1'b1;
                        top_st_q                  <= TOP_IDLE;
                    end else begin
                        sub_beat_q <= sub_beat_q + 4'd1;
                    end
                end
                default: top_st_q <= TOP_IDLE;
            endcase
        end
    end

    wire unused_mode_hold_ok = &{1'b0, CMD_NOP, cand_staged_pad_c[7:6]};
    assign ready_o         = (top_st_q == TOP_IDLE) & core_ready_w;
    assign step_done_o     = step_done_q;
    assign swap_done_o     = swap_done_q;
    assign swap_accepted_o = swap_acc_q;
    assign rd_data_o       = core_rd_data_w;

`ifdef FORMAL
    logic        f_past_valid_q;
    logic        f_past_rst_n_q;
    logic        f_past_ready_q;
    logic [2:0]  f_past_st_q;
    logic        f_past_fw_ok_q;
    logic [15:0] f_past_cap_q;
    logic [5:0]  f_past_mask_q;
    logic        f_past_b_ok_q;
    logic        f_past_dt_ok_q;
    logic [7:0]  f_past_nlo_q;
    logic [7:0]  f_past_nhi_q;
    initial f_past_valid_q = 1'b0;
    always @(posedge clk) begin
        f_past_valid_q <= 1'b1;
        f_past_rst_n_q <= rst_n;
        f_past_ready_q <= ready_o;
        f_past_st_q    <= top_st_q;
        f_past_fw_ok_q <= swap_fw_ok_c;
        f_past_cap_q   <= cap_mask_q;
        f_past_mask_q  <= cand_staged_mask_q;
        f_past_b_ok_q  <= cand_b_ok_q;
        f_past_dt_ok_q <= cand_dt_ok_q;
        f_past_nlo_q   <= cand_next_lo_q;
        f_past_nhi_q   <= cand_next_hi_q;
    end
    always_comb begin
        if (!rst_n) begin
            assert (top_st_q == TOP_IDLE);
            assert (!step_done_o && !swap_done_o && !swap_accepted_o);
            assert (cap_mask_q == HW_MASK16);
            assert (slot_valid_q == {MAX_CHARTS{1'b0}});
            assert (!bound_cache_valid_q);
            assert (cand_staged_mask_q == 6'd0 && cand_b_ok_q && !cand_dt_ok_q);
        end
        assert ((cap_mask_q & (~HW_MASK16)) == 16'd0);
        if ((top_st_q == TOP_IDLE) && (!core_ready_w)) begin
            assert (!ready_o && !sram_ce_c && !sram_we_c && !core_wr_valid_c);
        end
        if ((top_st_q == TOP_IDLE) && cmd_valid_i && core_ready_w && (cmd_op_i == CMD_STEP) && step_cache_hit_c) begin
            assert (!sram_ce_c && !sram_we_c);
        end
        if ((top_st_q == TOP_IDLE) && cmd_valid_i && core_ready_w && (cmd_op_i == CMD_STAGE_CAND) && (cmd_word_i < 3'd6)) begin
            assert (sram_ce_c && sram_we_c && (sram_addr_c == {SHADOW_SLOT, cmd_word_i}));
        end
        if ((top_st_q == TOP_FETCH_BOUND) || (top_st_q == TOP_START_CORE) || (top_st_q == TOP_WAIT_CORE)) begin
            assert (sram_we_c == 1'b0);
            assert (!ready_o);
        end
        if (top_st_q == TOP_SWAP_CHK) begin
            assert (sram_we_c == 1'b0);
            if (!swap_fw_ok_c) assert (sram_ce_c == 1'b0);
        end
        if ((top_st_q == TOP_SWAP_COMMIT) && sram_we_c) begin
            assert (sram_addr_c[SRAM_AW-1] == 1'b0);
        end
        if (f_past_valid_q && f_past_rst_n_q && rst_n) begin
            if (!f_past_ready_q) begin
                assert (cap_mask_q == f_past_cap_q);
                assert (cand_staged_mask_q == f_past_mask_q);
                assert (cand_b_ok_q == f_past_b_ok_q && cand_dt_ok_q == f_past_dt_ok_q);
                assert (cand_next_lo_q == f_past_nlo_q && cand_next_hi_q == f_past_nhi_q);
            end
            if ((f_past_st_q == TOP_WAIT_CORE)) begin
                assert (!swap_done_o && !swap_accepted_o);
            end
            if ((f_past_st_q == TOP_SWAP_CHK) && (!f_past_fw_ok_q)) begin
                assert (swap_done_o && !swap_accepted_o);
            end
        end
    end
`endif
endmodule

/* verilator lint_on DECLFILENAME */
`default_nettype wire
